INSERT INTO public.learning_days (date, week_number, day_in_week, day_type, title, description, resources, deliverable, completed_override)
VALUES
  ('2026-08-18', 1, 1, 'study', 'Set up the toolkit', 'Install Python 3.11+, VS Code, and create a venv. Create the GitHub repository that will hold all projects and code throughout this 6-month journey.', '[{"label": "Python Official Docs", "url": "https://docs.python.org/3/tutorial/venv.html"}]'::jsonb, 'GitHub repository initialized with README and Python 3.11 virtual environment', NULL),
  ('2026-08-19', 1, 2, 'study', 'Learn async/await', 'Work through the official Python asyncio docs; write three small practice async functions demonstrating concurrent fetching, task gathering, and timeouts.', '[{"label": "Python asyncio Documentation", "url": "https://docs.python.org/3/library/asyncio.html"}]'::jsonb, '3 functional asyncio scripts demonstrating concurrency patterns', NULL),
  ('2026-08-20', 1, 3, 'study', 'Learn Pydantic + type hints', 'Master Pydantic v2 data validation and strict typing. Model a complex sample API response as a Pydantic class with custom validators.', '[{"label": "Pydantic v2 Docs", "url": "https://docs.pydantic.dev/latest/"}]'::jsonb, 'Pydantic models with validation schemas for nested API payloads', NULL),
  ('2026-08-21', 1, 4, 'study', 'Build an Async CLI tool', 'Build an async command-line tool that concurrently calls a public REST API, parses and validates the JSON response with Pydantic, and outputs formatted results.', '[{"label": "HTTPX Async Client", "url": "https://www.python-httpx.org/async/"}]'::jsonb, 'Working async CLI utility in Python with error handling', NULL),
  ('2026-08-22', 1, 5, 'study', 'Polish & commit', 'Clean up the CLI tool, write a concise and informative README with usage examples, and push the first verified commit of the roadmap.', '[{"label": "Conventional Commits", "url": "https://www.conventionalcommits.org/"}]'::jsonb, 'Cleaned repo with documentation and passing CLI tests', NULL),
