  ('2026-08-25', 2, 1, 'study', 'ChatGPT Prompt Engineering for Developers (Part 1)', 'Complete the first half of DeepLearning.AI''s ''ChatGPT Prompt Engineering for Developers'' taught by Andrew Ng and Isa Fulford.', '[{"label": "DeepLearning.AI Prompt Engineering", "url": "https://www.deeplearning.ai/short-courses/chatgpt-prompt-engineering-for-developers/"}]'::jsonb, 'Course notebook with prompting principles 1 & 2 exercises', NULL),
  ('2026-08-26', 2, 2, 'study', 'ChatGPT Prompt Engineering for Developers (Part 2)', 'Finish the course. Implement each technique (summarizing, inferring, transforming, expanding) in a standalone Jupyter notebook.', '[{"label": "OpenAI Prompt Engineering Guide", "url": "https://platform.openai.com/docs/guides/prompt-engineering"}]'::jsonb, 'Complete interactive Jupyter notebook covering all core prompting strategies', NULL),
  ('2026-08-27', 2, 3, 'study', 'Chip Huyen''s AI Engineering — Intro Chapter', 'Start Chip Huyen''s book ''AI Engineering'' (O''Reilly, 2025). Read the introduction chapter and explore the companion code repository.', '[{"label": "Chip Huyen AI Engineering Companion", "url": "https://github.com/chiphuyen/aie-book"}]'::jsonb, 'Reading notes and environment setup for book companion code', NULL),
  ('2026-08-28', 2, 4, 'study', 'AI Engineering — Prompting Chapter', 'Continue Chip Huyen''s book, studying the in-depth prompting chapter. Analyze prompt optimization, token budgets, and prompt compression.', '[{"label": "AI Engineering Book", "url": "https://huyenchip.com/"}]'::jsonb, 'Summary of prompt engineering trade-offs and token optimization rules', NULL),
  ('2026-08-29', 2, 5, 'study', 'Prompting Strategy Comparison', 'Write a short benchmark comparison comparing few-shot vs. chain-of-thought (CoT) vs. structured-output prompting on a non-trivial classification/extraction task.', '[{"label": "Chain-of-Thought Paper (Wei et al.)", "url": "https://arxiv.org/abs/2201.11903"}]'::jsonb, 'Markdown report with sample prompts, outputs, and cost/accuracy comparison', NULL),
