  ('2026-09-01', 3, 1, 'study', 'Claude 101', 'Sign up at anthropic.skilljar.com; complete the ''Claude 101'' foundational course covering model capabilities, system prompts, and context windows.', '[{"label": "Anthropic Educational Academy", "url": "https://anthropic.skilljar.com"}]'::jsonb, 'Course completion badge & initial Anthropic SDK script', NULL),
  ('2026-09-02', 3, 2, 'study', 'Building with the Claude API — Auth & Requests', 'Work through ''Building with the Claude API'' modules on authentication, client setup, basic message requests, and parameter tuning (temperature, max_tokens).', '[{"label": "Anthropic API Quickstart", "url": "https://docs.anthropic.com/en/api/getting-started"}]'::jsonb, 'Python script with robust Anthropic client initialization and request wrappers', NULL),
  ('2026-09-03', 3, 3, 'study', 'Streaming & Tool Use Modules', 'Complete the streaming responses and tool use (function calling) modules in Anthropic Academy. Implement real-time SSE token streaming.', '[{"label": "Claude Tool Use Guide", "url": "https://docs.anthropic.com/en/docs/tool-use"}]'::jsonb, 'Streaming terminal chat client using Claude API with JSON schema tool definitions', NULL),
  ('2026-09-04', 3, 4, 'study', 'Prompt Caching & Error Handling', 'Master Claude''s Prompt Caching to slash latency and cost by up to 90%. Implement exponential backoff, rate limit handling, and API error categorization.', '[{"label": "Prompt Caching Documentation", "url": "https://docs.anthropic.com/en/docs/prompt-caching"}]'::jsonb, 'Cached prompt pipeline with verified cache_read_input_tokens reduction', NULL),
  ('2026-09-05', 3, 5, 'study', 'Production Deployment Patterns', 'Study production deployment patterns module: secret management, latency optimizations, batch API requests, and monitoring token consumption.', '[{"label": "Anthropic Production Best Practices", "url": "https://docs.anthropic.com/en/docs/production-readiness"}]'::jsonb, 'Production-ready Claude client class with telemetry logging', NULL),
