  ('2026-09-08', 4, 1, 'study', 'Finish Anthropic Academy Certification', 'Finish any remaining modules in ''Building with the Claude API'' and review the consolidated architecture patterns.', '[{"label": "Anthropic Interactive Tutorials", "url": "https://github.com/anthropics/anthropic-sdk-python"}]'::jsonb, 'Complete course certification and cheat-sheet summary', NULL),
  ('2026-09-09', 4, 2, 'study', 'Design Project #0: CLI Chatbot with Memory', 'Design Project #0 (CLI chatbot with structured conversation memory). Sketch the memory buffer architecture and message trimming strategy.', '[{"label": "System Architecture Sketching", "url": "https://github.com/AlirezaNezami96"}]'::jsonb, 'Architecture diagram and technical specification document', NULL),
  ('2026-09-10', 4, 3, 'study', 'Build Core Chat Loop & Memory Buffer', 'Build the core conversational loop in Python. Implement sliding-window memory with token counting to maintain context without overflowing limits.', '[{"label": "Tiktoken / Anthropic Tokenizer", "url": "https://github.com/openai/tiktoken"}]'::jsonb, 'Working stateful chat engine with memory persistence across sessions', NULL),
  ('2026-09-11', 4, 4, 'study', 'Add Error Handling & Retry Logic', 'Add graceful connection loss handling, network retry backoff, graceful interruption (Ctrl+C), and formatted markdown terminal output with Rich.', '[{"label": "Rich Terminal Library", "url": "https://rich.readthedocs.io/"}]'::jsonb, 'Beautiful terminal UI with streaming markdown and resilient exception handling', NULL),
  ('2026-09-12', 4, 5, 'study', 'Project #0 Done — Polish, README & Commit', 'Polish the CLI chatbot, write comprehensive README with setup instructions and architecture breakdown, and tag release. Project #0 completed!', '[{"label": "Project #0 GitHub Repo", "url": "https://github.com/AlirezaNezami96"}]'::jsonb, '⭐ Project #0 (''CLI AI Assistant with Context Memory'') published to GitHub', NULL),
