  ('2026-09-15', 5, 1, 'study', 'Understanding & Applying Text Embeddings', 'Complete DeepLearning.AI''s ''Understanding and Applying Text Embeddings''. Study vector spaces, cosine similarity, and semantic search fundamentals.', '[{"label": "DeepLearning.AI Text Embeddings", "url": "https://www.deeplearning.ai/short-courses/google-cloud-vertex-ai/"}]'::jsonb, 'Cosine similarity calculator and embedding visualization script', NULL),
  ('2026-09-16', 5, 2, 'study', 'Vector Databases: From Embeddings to Applications (Part 1)', 'Work through the first half of DeepLearning.AI''s ''Vector Databases: from Embeddings to Applications'' covering ANN algorithms (HNSW, IVF).', '[{"label": "DeepLearning.AI Vector Databases", "url": "https://www.deeplearning.ai/short-courses/vector-databases-embeddings-applications/"}]'::jsonb, 'Notes on HNSW graph indexing vs Flat search complexity', NULL),
  ('2026-09-17', 5, 3, 'study', 'Vector Databases (Part 2)', 'Finish the vector database course. Practice filtered search, metadata payload indexing, and multi-tenant namespace isolation.', '[{"label": "Qdrant Vector Database Docs", "url": "https://qdrant.tech/documentation/"}]'::jsonb, 'Course completion exercises and benchmark comparisons', NULL),
  ('2026-09-18', 5, 4, 'study', 'Set up Local Qdrant / Chroma', 'Install and run Qdrant or Chroma locally via Docker or in-memory Python client. Index a small test dataset and execute top-k semantic similarity queries.', '[{"label": "Chroma DB Quickstart", "url": "https://docs.trychroma.com/"}]'::jsonb, 'Local vector store instance running with automated collection initialization', NULL),
  ('2026-09-19', 5, 5, 'study', 'Index Personal Knowledge Corpus', 'Chunk, embed, and index a real personal corpus — your résumé, cover letters, and project READMEs. Validate chunk overlap and embedding consistency.', '[{"label": "Chunking Strategies Guide", "url": "https://www.pinecone.io/learn/chunking-strategies/"}]'::jsonb, 'Fully indexed personal knowledge vector collection with metadata tags', NULL),
