  ('2026-09-22', 6, 1, 'study', 'LangChain / LlamaIndex: Chat with Your Data (Part 1)', 'Start DeepLearning.AI''s ''LangChain: Chat with Your Data'' / LlamaIndex quickstart. Study document loaders, text splitters, and vector store retrievers.', '[{"label": "LangChain Chat with Data", "url": "https://www.deeplearning.ai/short-courses/langchain-chat-with-your-data/"}]'::jsonb, 'Document ingestion script with semantic sentence-splitting', NULL),
  ('2026-09-23', 6, 2, 'study', 'LangChain / LlamaIndex (Part 2)', 'Finish the course. Master retrieval augmentation chains, question-answering with sources, and conversational retrieval with chat history.', '[{"label": "LlamaIndex Documentation", "url": "https://docs.llamaindex.ai/"}]'::jsonb, 'End-to-end RAG chain combining query rewriting and context assembly', NULL),
  ('2026-09-24', 6, 3, 'study', 'Scaffold RAG Pipeline v1', 'Scaffold a clean Python RAG architecture: query processing → similarity retrieval → prompt injection → grounded generation.', '[{"label": "RAG Architecture Blueprint", "url": "https://github.com/AlirezaNezami96"}]'::jsonb, 'Modular RAG v1 pipeline with clean separation of retriever and generator', NULL),
  ('2026-09-25', 6, 4, 'study', 'Connect Personal Career Corpus', 'Connect the RAG pipeline to the personal corpus indexed in Week 5. Tune prompt templates to cite source documents with exact line/section references.', '[{"label": "Grounding and Citation Prompts", "url": "https://docs.anthropic.com"}]'::jsonb, 'Interactive Q&A assistant answering questions about Alireza''s career and projects', NULL),
  ('2026-09-26', 6, 5, 'study', 'Test RAG v1 & Document Failure Cases', 'Test with 10 challenging sample questions. Document failure cases: hallucinated details, missing context, and chunk boundary truncations.', '[{"label": "RAG Failure Modes Analysis", "url": "https://arxiv.org/abs/2312.10997"}]'::jsonb, 'Evaluation log of 10 test queries with identified retrieval bottlenecks', NULL),
