  ('2026-09-29', 7, 1, 'study', 'Advanced Retrieval for AI (Part 1)', 'Start DeepLearning.AI''s ''Advanced Retrieval for AI with Chroma''. Study query expansion, cross-encoder rerankers, and dense + sparse hybrid search.', '[{"label": "DeepLearning.AI Advanced Retrieval", "url": "https://www.deeplearning.ai/short-courses/advanced-retrieval-for-ai/"}]'::jsonb, 'Course notebook with cross-encoder re-ranking experiments', NULL),
  ('2026-09-30', 7, 2, 'study', 'Advanced Retrieval for AI (Part 2)', 'Finish the advanced retrieval course. Learn Reciprocal Rank Fusion (RRF) and contextual compression techniques.', '[{"label": "FlashRank / Cohere Rerank", "url": "https://github.com/PrithivirajDamodaran/FlashRank"}]'::jsonb, 'RRF fusion implementation script combining BM25 and vector scores', NULL),
  ('2026-10-01', 7, 3, 'study', 'Implement Hybrid Retrieval (BM25 + Vector)', 'Add BM25 keyword search alongside vector embeddings (hybrid retrieval). Combine scores with rank fusion to handle exact keywords & acronyms.', '[{"label": "Rank-BM25 Python Package", "url": "https://github.com/dorianbrown/rank_bm25"}]'::jsonb, 'Hybrid retriever returning balanced semantic and keyword search hits', NULL),
  ('2026-10-02', 7, 4, 'study', 'Add FlashRank / Cohere Reranking Step', 'Integrate a neural re-ranking step (FlashRank for local or Cohere Rerank API). Filter top-25 candidate chunks down to top-5 high-relevance chunks.', '[{"label": "Cohere Rerank Docs", "url": "https://docs.cohere.com/docs/reranking"}]'::jsonb, 'Re-ranking module integrated into retrieval pipeline with latency benchmarks', NULL),
  ('2026-10-03', 7, 5, 'study', 'Benchmark RAG v1 vs. RAG v2', 'Run the 10 sample questions from Week 6 against RAG v2. Compare answer precision, citation accuracy, and hallucination reduction.', '[{"label": "RAG v1 vs v2 Benchmark", "url": "https://github.com/AlirezaNezami96"}]'::jsonb, 'Side-by-side comparative evaluation sheet highlighting v2 improvements', NULL),
