  ('2026-10-08', 8, 3, 'study', 'Execute Faithfulness & Answer Relevance Scoring', 'Run automated RAGAS evaluation: measure context precision, context recall, faithfulness, and answer relevance across the test set.', '[{"label": "RAGAS Metrics Guide", "url": "https://docs.ragas.io/en/latest/concepts/metrics/"}]'::jsonb, 'Evaluation report with numerical scores for Faithfulness and Relevance', NULL),
